corrected_code:
const Redis = require('ioredis');
const redis = new Redis(process.env.REDIS_URL);
const axios = require('axios');
const { WebhookEndpoint } = require('../models');

async function runWebhookStreamProcessor() {
  while (true) {
    const entries = await redis.xreadgroup('GROUP', 'wh-dispatcher', 'node-1', 'BLOCK', 2000, 'STREAMS', 'stream:webhook:dispatch', '>');
    if (!entries) continue;

    for (const [, msgs] of entries) {
      for (const [msgId, values] of msgs) {
        const { endpointId, tenantId, payloadJson } = JSON.parse(values[1]);

        const endpoint = await WebhookEndpoint.findOne({ where: { id: endpointId, tenantId } });
        if (endpoint) {
          await axios.post(endpoint.targetUrl, JSON.parse(payloadJson), { timeout: 5000 });
        }
        await redis.xack('stream:webhook:dispatch', 'wh-dispatcher', msgId);
      }
    }
  }
}
